    public void S14_TheCheckoutQuoteAddsShippingToThePayableTotal(
        int subtotalCents, LoyaltyTier tier, string? code, bool express, int payableCents, int shippingCents, int totalCents)
    {
        var quote = _useCase.Handle(new QuoteCheckoutQuery(subtotalCents, tier, code, express));

        Assert.Equal(payableCents, quote.PayableCents);
        Assert.Equal(shippingCents, quote.ShippingCents);
        Assert.Equal(totalCents, quote.TotalCents);
    }
}

