using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public sealed class CalculateLoyaltyDiscountAcceptanceTests
{
    private readonly CalculateLoyaltyDiscount _useCase = new();

    // Member receives the loyalty discount of their tier
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 500, 9500)]
    [InlineData(LoyaltyTier.Silver, 1000, 9000)]
    [InlineData(LoyaltyTier.Gold, 1500, 8500)]
    public void S1_MemberReceivesTheLoyaltyDiscountOfTheirTier(LoyaltyTier tier, int discountCents, int totalCents)
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, tier));

        Assert.Equal(discountCents, quote.DiscountCents);
        Assert.Equal(totalCents, quote.TotalCents);
    }

    // The loyalty discount never exceeds 20.00 EUR
    [Theory]
    [InlineData(20000, LoyaltyTier.Gold, 2000, 18000)]
    [InlineData(30000, LoyaltyTier.Silver, 2000, 28000)]
    [InlineData(12000, LoyaltyTier.Gold, 1800, 10200)]
    public void S2_TheLoyaltyDiscountNeverExceeds20Euros(int subtotalCents, LoyaltyTier tier, int discountCents, int totalCents)
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(discountCents, quote.DiscountCents);
        Assert.Equal(totalCents, quote.TotalCents);
    }

    // No loyalty discount under a 30.00 EUR subtotal
    [Theory]
    [InlineData(2999, 0, 2999)]
    [InlineData(3000, 450, 2550)]
    public void S3_NoLoyaltyDiscountUnder30Euros(int subtotalCents, int discountCents, int totalCents)
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, LoyaltyTier.Gold));

        Assert.Equal(discountCents, quote.DiscountCents);
        Assert.Equal(totalCents, quote.TotalCents);
    }

    // The WELCOME5 promo code takes 5.00 EUR off after the loyalty discount
    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, 1500, 8500)]
    [InlineData(2000, LoyaltyTier.Bronze, 500, 1500)]
    public void S4_Welcome5TakesFiveEurosOffAfterTheLoyaltyDiscount(int subtotalCents, LoyaltyTier tier, int discountCents, int totalCents)
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier, "WELCOME5"));

        Assert.Equal(discountCents, quote.DiscountCents);
        Assert.Equal(totalCents, quote.TotalCents);
    }

    // The cap applies to the loyalty discount only, never to WELCOME5
    [Theory]
    [InlineData(20000, LoyaltyTier.Gold, 2500, 17500)]
    [InlineData(30000, LoyaltyTier.Silver, 2500, 27500)]
    public void S5_TheCapAppliesToTheLoyaltyDiscountOnly(int subtotalCents, LoyaltyTier tier, int discountCents, int totalCents)
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier, "WELCOME5"));

        Assert.Equal(discountCents, quote.DiscountCents);
        Assert.Equal(totalCents, quote.TotalCents);
    }

    // Promo codes ignore case
    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodesIgnoreCase(string code)
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver, code));

        Assert.Equal(1500, quote.DiscountCents);
    }

    // The SUMMER10 promo code takes 10 % off what is left, at most 15.00 EUR
    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, 1900, 8100)]
    [InlineData(30000, LoyaltyTier.Bronze, 3000, 27000)]
    [InlineData(2000, LoyaltyTier.Gold, 200, 1800)]
    public void S7_Summer10TakesTenPercentOffWhatIsLeftAtMost15Euros(int subtotalCents, LoyaltyTier tier, int discountCents, int totalCents)
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier, "SUMMER10"));

        Assert.Equal(discountCents, quote.DiscountCents);
        Assert.Equal(totalCents, quote.TotalCents);
    }

    // An unknown promo code is ignored
    [Fact]
    public void S8_AnUnknownPromoCodeIsIgnored()
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver, "SPRING"));

        Assert.Equal(1000, quote.DiscountCents);
        Assert.Equal(9000, quote.TotalCents);
    }

    // Platinum members receive a 20 % loyalty discount
    [Theory]
    [InlineData(10000, 2000, 8000)]
    [InlineData(5000, 1000, 4000)]
    [InlineData(20000, 2000, 18000)]
    public void S9_PlatinumMembersReceiveA20PercentLoyaltyDiscount(int subtotalCents, int discountCents, int totalCents)
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, LoyaltyTier.Platinum));

        Assert.Equal(discountCents, quote.DiscountCents);
        Assert.Equal(totalCents, quote.TotalCents);
    }

    // The discount never exceeds the subtotal
    [Theory]
    [InlineData(400, LoyaltyTier.Bronze, 400)]
    [InlineData(300, LoyaltyTier.Gold, 300)]
    public void S10_TheDiscountNeverExceedsTheSubtotal(int subtotalCents, LoyaltyTier tier, int discountCents)
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier, "WELCOME5"));

        Assert.Equal(discountCents, quote.DiscountCents);
        Assert.Equal(0, quote.TotalCents);
    }
}

